---RefreshUI
---@param monsterTypeVo MonsterTypeVo
---@param position number
function UIBossDetailHeadNodeMB:RefreshUI(monsterTypeVo, position)
    local headNode = self.CommonSmallHeadNode
    self.position = position

    --KTool.SetActive(self.BossIcon.gameObject, monsterTypeVo.monsterClass == Constants.RoleClass.Boss)

    ---@type CardHeadNode
    local mbEnv = CfUtils.GetLuaScr(headNode.gameObject, PrefabPathHeadNode)
    if mbEnv == nil then return end

    local rare
    local monsterClass = monsterTypeVo.monsterClass
    if monsterClass == Constants.RoleClass.Boss then
        rare = Constants.RareType.SSR
    elseif monsterClass == Constants.RoleClass.Elite then
        rare = Constants.RareType.SR
    else
        rare = Constants.RareType.R
    end

    mbEnv:FreshMonsterUI(monsterTypeVo, rare)
    mbEnv:SetBossMarkStatus(monsterClass == Constants.RoleClass.Boss)
end

function UIBossDetailHeadNodeMB:RefreshShowState(isSelect)
    self.CommonSmallHeadNode.localScale = isSelect and SCALE8 or SCALE6
    KTool.SetActive(self.SelectImage.gameObject, isSelect)
end

